CREATE TABLE turmas (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, curso TEXT NOT NULL DEFAULT '', periodo TEXT NOT NULL DEFAULT '', ativa INTEGER NOT NULL DEFAULT 1, criado_em TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE atividades (id INTEGER PRIMARY KEY AUTOINCREMENT, titulo TEXT NOT NULL, codigo TEXT NOT NULL UNIQUE COLLATE NOCASE, ativa INTEGER NOT NULL DEFAULT 1, modo TEXT NOT NULL DEFAULT 'treino' CHECK (modo IN ('treino','prova','ao_vivo')), tempo_total INTEGER, tempo_por_questao INTEGER, tentativas_max INTEGER, feedback TEXT NOT NULL DEFAULT 'imediato' CHECK (feedback IN ('imediato','final','nenhum')), navegacao TEXT NOT NULL DEFAULT 'livre' CHECK (navegacao IN ('livre','sequencial')), embaralhar INTEGER NOT NULL DEFAULT 0, conta_nota INTEGER NOT NULL DEFAULT 0, abre_em TEXT, fecha_em TEXT, modelo_cabecalho_id INTEGER, criado_em TEXT NOT NULL DEFAULT (datetime('now')), atualizado_em TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE atividade_questoes (atividade_id INTEGER NOT NULL REFERENCES atividades(id), questao_id INTEGER NOT NULL REFERENCES questoes(id), ordem INTEGER NOT NULL, pontos REAL, PRIMARY KEY (atividade_id, questao_id));
CREATE TABLE atividade_turmas (atividade_id INTEGER NOT NULL REFERENCES atividades(id), turma_id INTEGER NOT NULL REFERENCES turmas(id), PRIMARY KEY (atividade_id, turma_id));
CREATE TABLE tentativas (id INTEGER PRIMARY KEY AUTOINCREMENT, atividade_id INTEGER NOT NULL REFERENCES atividades(id), token TEXT NOT NULL UNIQUE, nome TEXT NOT NULL, turma_id INTEGER NOT NULL REFERENCES turmas(id), email TEXT NOT NULL COLLATE NOCASE, inicio_em TEXT NOT NULL, prazo_em TEXT, acrescimo_segundos INTEGER NOT NULL DEFAULT 0, questoes TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'andamento' CHECK (status IN ('andamento','finalizada')), finalizada_em TEXT, nota REAL, pontos_max REAL);
CREATE INDEX idx_tentativas_atividade ON tentativas(atividade_id, email);
CREATE TABLE respostas (tentativa_id INTEGER NOT NULL REFERENCES tentativas(id), questao_id INTEGER NOT NULL, resposta TEXT NOT NULL, pontos_auto REAL, pontos_final REAL, status TEXT NOT NULL DEFAULT 'corrigida', PRIMARY KEY (tentativa_id, questao_id));
